    return np.linalg.lstsq(a, b, rcond=None)[0]


def _aff(x):
    return np.column_stack((np.ones(len(x)), x))


def _features(w, gain, interaction, kind):
    u = gain * w
    if kind == 'atan':
        z = np.arctan(u)
    elif kind == 'inv3':
        z = np.sinh(np.arcsinh(u) / 3)
    else:
        z = np.arcsinh(u)
    if not interaction:
